const row = $input.first() ? $input.first().json : {};

let ev = {};
try {
  ev = typeof row.evidence_json === "string" ? JSON.parse(row.evidence_json) : (row.evidence_json || {});
} catch (e) {
  ev = {};
}

const val = (v) => (v === undefined || v === null || v === "") ? null : v;
const arr = (a) => Array.isArray(a) ? a : [];

const ai = (ev.ai_analysis && typeof ev.ai_analysis === "object") ? ev.ai_analysis : {};
const vt = ev.virustotal != null ? ev.virustotal : null;
const ent = (ev.extracted_entities && typeof ev.extracted_entities === "object") ? ev.extracted_entities : {};

const incident_id = ev.scan_id != null ? ev.scan_id : (row.scan_id != null ? row.scan_id : null);

// Structured report object — kept in the workflow for later PDF/email phases.
const report = {
  title: "TRUTHLENSAI INCIDENT REPORT",
  incident_id: incident_id,
  scan_id: val(ev.scan_id),
  timestamp: val(ev.timestamp),
  platform: val(ev.platform),
  input_type: val(ev.input_type),
  risk_score: ev.risk_score != null ? ev.risk_score : null,
  severity: val(ev.severity),
  confidence: val(ev.confidence),
  threat_type: val(ev.threat_type),
  original_content: {
    original_text: val(ev.original_text),
    extracted_text: val(ev.extracted_text)
  },
  extracted_entities: {
    urls: arr(ent.urls),
    upi_ids: arr(ent.upi_ids),
    phone_numbers: arr(ent.phone_numbers),
    emails: arr(ent.emails)
  },
  detected_signals: arr(ev.evidence),
  ai_analysis: {
    scam_intent: ai.scam_intent !== undefined ? ai.scam_intent : null,
    social_engineering: ai.social_engineering !== undefined ? ai.social_engineering : null,
    impersonation: ai.impersonation !== undefined ? ai.impersonation : null,
    financial_manipulation: ai.financial_manipulation !== undefined ? ai.financial_manipulation : null,
    urgency: ai.urgency !== undefined ? ai.urgency : null,
    confidence: ai.confidence !== undefined ? ai.confidence : null,
    explanation: ai.explanation !== undefined ? ai.explanation : null,
    threat_type: ai.threat_type !== undefined ? ai.threat_type : null
  },
  virustotal: vt,
  recommendation: val(ev.recommendation)
};

// Human-readable text version, faithful to real values only.
const lines = [];
const show = (label, v) => { lines.push(label + ": " + (v === null || v === undefined || v === "" ? "(not available)" : v)); };

lines.push("🚨 TRUTHLENSAI INCIDENT REPORT");
lines.push("");
show("Incident ID", report.incident_id);
show("Scan ID", report.scan_id);
show("Timestamp", report.timestamp);
show("Platform", report.platform);
show("Input Type", report.input_type);
show("Risk Score", report.risk_score);
show("Severity", report.severity);
show("Confidence", report.confidence);
show("Threat Type", report.threat_type);
lines.push("");
lines.push("── ORIGINAL CONTENT ──");
if (report.original_content.original_text != null) lines.push("Original Text:\n" + report.original_content.original_text);
if (report.original_content.extracted_text != null) lines.push("Extracted Text (OCR):\n" + report.original_content.extracted_text);
if (report.original_content.original_text == null && report.original_content.extracted_text == null) lines.push("(not available)");
lines.push("");
lines.push("── EXTRACTED ENTITIES ──");
show("URLs", report.extracted_entities.urls.join(", "));
show("UPI IDs", report.extracted_entities.upi_ids.join(", "));
show("Phone Numbers", report.extracted_entities.phone_numbers.join(", "));
show("Emails", report.extracted_entities.emails.join(", "));
lines.push("");
lines.push("── DETECTED SIGNALS ──");
if (report.detected_signals.length) {
  for (const s of report.detected_signals) {
    const text = (s && typeof s === "object") ? (s.signal || JSON.stringify(s)) : s;
    lines.push("• " + text);
  }
} else {
  lines.push("(none)");
}
lines.push("");
lines.push("── AI ANALYSIS ──");
show("Scam Intent", report.ai_analysis.scam_intent);
show("Social Engineering", report.ai_analysis.social_engineering);
show("Impersonation", report.ai_analysis.impersonation);
show("Financial Manipulation", report.ai_analysis.financial_manipulation);
show("Urgency", report.ai_analysis.urgency);
show("Confidence", report.ai_analysis.confidence);
show("Threat Type", report.ai_analysis.threat_type);
show("Explanation", report.ai_analysis.explanation);
lines.push("");
lines.push("── VIRUSTOTAL ──");
if (report.virustotal != null) {
  lines.push(typeof report.virustotal === "object" ? JSON.stringify(report.virustotal, null, 2) : String(report.virustotal));
} else {
  lines.push("(not available)");
}
lines.push("");
lines.push("── RECOMMENDATION ──");
lines.push(report.recommendation != null ? report.recommendation : "(not available)");

const report_text = lines.join("\n");

return [{ json: { incident_id: incident_id, incident_report: report, report_text: report_text } }];

const gen = $('Generate Incident Report').first().json;
const r = (gen && gen.incident_report) ? gen.incident_report : {};

const esc = (v) => (v === null || v === undefined) ? "" : String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const incident_id = r.incident_id != null ? r.incident_id : "N/A";
const threat_type = r.threat_type != null ? r.threat_type : "Unknown";
const subject = "TruthLensAI Incident Report — " + incident_id + " — " + threat_type;

const tdKey = "padding:6px 12px;border:1px solid #ddd;background:#f7f7f7;font-weight:bold;width:38%;";
const tdVal = "padding:6px 12px;border:1px solid #ddd;";
const rawRow = (label, value) => "<tr><td style=\"" + tdKey + "\">" + esc(label) + "</td><td style=\"" + tdVal + "\">" + (value === null || value === undefined || value === "" ? "Not available" : value) + "</td></tr>";
const row = (label, value) => rawRow(label, (value === null || value === undefined || value === "") ? "Not available" : esc(value));
const tableOpen = "<table style=\"border-collapse:collapse;width:100%;font-size:14px;\">";
const section = (title, body) => "<h2 style=\"color:#b00020;border-bottom:2px solid #b00020;padding-bottom:4px;margin-top:28px;font-size:17px;\">" + esc(title) + "</h2>" + body;

// 1. Overview
const overview = [
  tableOpen,
  row("Incident ID", r.incident_id),
  row("Scan ID", r.scan_id),
  row("Timestamp", r.timestamp),
  row("Platform", r.platform),
  row("Input Type", r.input_type),
  row("Threat Type", r.threat_type),
  row("Risk Score", r.risk_score != null ? r.risk_score + "/100" : null),
  row("Severity", r.severity),
  row("Confidence", r.confidence),
  rawRow("Current Reporting Status", "Prepared (development mode — external reporting not connected)"),
  "</table>"
].join("");

// 2. Summary (only from available values, no invented facts)
let summaryText = "This incident was flagged by TruthLensAI";
if (r.platform) summaryText += " on the " + r.platform + " platform";
if (r.threat_type) summaryText += " as a potential " + r.threat_type + " threat";
summaryText += ". ";
summaryText += (r.risk_score != null) ? ("It received a risk score of " + r.risk_score + "/100") : "A risk score was not recorded";
if (r.severity) summaryText += " with a severity rating of " + r.severity;
if (r.confidence) summaryText += " and " + r.confidence + " confidence";
summaryText += ".";

// 3. Original content
const oc = r.original_content || {};
const preStyle = "white-space:pre-wrap;word-break:break-word;background:#f4f4f4;padding:10px;border:1px solid #ddd;font-size:13px;";
let ocHtml;
if (r.input_type === "image" && oc.extracted_text) {
  ocHtml = "<p><strong>Extracted OCR Text:</strong></p><pre style=\"" + preStyle + "\">" + esc(oc.extracted_text) + "</pre>";
} else if (oc.original_text) {
  ocHtml = "<p><strong>Original Message (as received):</strong></p><pre style=\"" + preStyle + "\">" + esc(oc.original_text) + "</pre>";
} else if (oc.extracted_text) {
  ocHtml = "<p><strong>Extracted OCR Text:</strong></p><pre style=\"" + preStyle + "\">" + esc(oc.extracted_text) + "</pre>";
} else {
  ocHtml = "<p>Original content not available for this incident.</p>";
}

// 4. Detected indicators
const signals = Array.isArray(r.detected_signals) ? r.detected_signals : [];
let sigHtml;
if (signals.length) {
  sigHtml = "<ul style=\"font-size:14px;\">" + signals.map(s => {
    const text = (s && typeof s === "object") ? (s.signal || JSON.stringify(s)) : s;
    return "<li>" + esc(text) + "</li>";
  }).join("") + "</ul>";
} else {
  sigHtml = "<p>No specific indicators were recorded for this incident.</p>";
}

// 5. Extracted entities (skip empty sections)
const ent = r.extracted_entities || {};
const entRows = [];
const addEnt = (label, a) => { if (Array.isArray(a) && a.length) entRows.push(row(label, a.join(", "))); };
addEnt("URLs", ent.urls);
addEnt("UPI IDs", ent.upi_ids);
addEnt("Phone Numbers", ent.phone_numbers);
addEnt("Email Addresses", ent.emails);
const entHtml = entRows.length ? (tableOpen + entRows.join("") + "</table>") : "<p>No entities were extracted from this incident.</p>";

// 6. AI assessment
const ai = r.ai_analysis || {};
const aiBool = (v) => v === true ? "Detected" : (v === false ? "Not detected" : (v == null ? "Not available" : esc(v)));
const aiHtml = [
  tableOpen,
  rawRow("Scam Intent", aiBool(ai.scam_intent)),
  rawRow("Social Engineering", aiBool(ai.social_engineering)),
  rawRow("Impersonation", aiBool(ai.impersonation)),
  rawRow("Financial Manipulation", aiBool(ai.financial_manipulation)),
  rawRow("Urgency", ai.urgency != null ? esc(ai.urgency) : "Not available"),
  rawRow("Confidence", ai.confidence != null ? esc(ai.confidence) : "Not available"),
  rawRow("AI Threat Type", ai.threat_type != null ? esc(ai.threat_type) : "Not available"),
  rawRow("AI Explanation", ai.explanation != null ? esc(ai.explanation) : "Not available"),
  "</table>"
].join("");

// 7. VirusTotal
const vt = r.virustotal;
const isEmptyObj = (o) => o && typeof o === "object" && !Array.isArray(o) && Object.keys(o).length === 0;
let vtHtml;
if (vt === null || vt === undefined || isEmptyObj(vt)) {
  vtHtml = "<p>VirusTotal: No result available for this incident.</p>";
} else if (typeof vt === "object") {
  const stats = (vt.stats && typeof vt.stats === "object") ? vt.stats : vt;
  const vtUrl = vt.url != null ? vt.url : (vt.value != null ? vt.value : null);
  const vtStatus = vt.status != null ? vt.status : (vt.vt_status != null ? vt.vt_status : null);
  const g = (k) => (stats && stats[k] != null) ? stats[k] : null;
  const rows2 = [];
  if (vtUrl != null) rows2.push(row("URL", vtUrl));
  if (vtStatus != null) rows2.push(row("Status", vtStatus));
  if (g("malicious") != null) rows2.push(row("Malicious Engines", g("malicious")));
  if (g("suspicious") != null) rows2.push(row("Suspicious Engines", g("suspicious")));
  if (g("harmless") != null) rows2.push(row("Harmless Engines", g("harmless")));
  if (g("undetected") != null) rows2.push(row("Undetected Engines", g("undetected")));
  vtHtml = rows2.length ? (tableOpen + rows2.join("") + "</table>") : "<p>VirusTotal: No result available for this incident.</p>";
} else {
  vtHtml = "<p>" + esc(String(vt)) + "</p>";
}

// 8. Recommendation
const recHtml = "<p>" + (r.recommendation != null ? esc(r.recommendation) : "No specific recommendation was recorded for this incident.") + "</p>";

// 9. Evidence / reporting status
const statusHtml = tableOpen + rawRow("Evidence Pack", "Prepared") + rawRow("Incident Report", "Generated") + rawRow("External Reporting", "Not connected") + "</table>";

const html = [
  "<div style=\"font-family:Arial,Helvetica,sans-serif;color:#222;max-width:800px;margin:0 auto;\">",
  "<div style=\"background:#b00020;color:#fff;padding:16px 20px;border-radius:6px;\">",
  "<h1 style=\"margin:0;font-size:22px;\">🚨 TruthLensAI Incident Report</h1>",
  "<p style=\"margin:6px 0 0;font-size:13px;\">Incident ID: " + esc(incident_id) + " &nbsp;|&nbsp; Threat Type: " + esc(threat_type) + "</p>",
  "</div>",
  "<p style=\"font-size:12px;color:#888;\">Development / demo report. This workflow does not contact any external authority.</p>",
  section("1. Incident Overview", overview),
  section("2. Incident Summary", "<p style=\"font-size:14px;\">" + esc(summaryText) + "</p>"),
  section("3. Original Content", ocHtml),
  section("4. Detected Indicators", sigHtml),
  section("5. Extracted Entities", entHtml),
  section("6. AI Assessment", aiHtml),
  section("7. VirusTotal Findings", vtHtml),
  section("8. Recommended Action", recHtml),
  section("9. Evidence / Reporting Status", statusHtml),
  "<p style=\"font-size:11px;color:#999;margin-top:30px;\">Generated by TruthLensAI • Development reporting workflow</p>",
  "</div>"
].join("");

const safeId = String(incident_id).replace(/[^a-zA-Z0-9_-]/g, "_");
const fileName = "TruthLensAI_Incident_Report_" + safeId + ".html";

return [{
  json: { subject: subject, incident_id: incident_id, threat_type: threat_type, email_html: html },
  binary: {
    report: {
      data: Buffer.from(html, "utf8").toString("base64"),
      fileName: fileName,
      mimeType: "text/html"
    }
  }
}];

