const out = [];

for (const item of $input.all()) {
  const d = (item && item.json) ? item.json : {};

  // --- Core gate values (safe reads, no invented values) ---
  const riskScore = Number(d.risk_score);
  const confidence = d.confidence;

  // --- Strong corroborating indicators ---
  // VirusTotal malicious count (check common shapes, default 0)
  const vt = (d.virustotal && typeof d.virustotal === "object") ? d.virustotal : {};
  const vtStats = (vt.stats && typeof vt.stats === "object") ? vt.stats : {};
  const vtMalicious = Number(
    vt.malicious != null ? vt.malicious : (vtStats.malicious != null ? vtStats.malicious : 0)
  ) || 0;

  // AI scam intent (check ai_analysis then top-level, default false)
  const ai = (d.ai_analysis && typeof d.ai_analysis === "object") ? d.ai_analysis : {};
  const scamIntent = (ai.scam_intent === true) || (d.scam_intent === true);

  // Multiple evidence signals
  const evidence = Array.isArray(d.evidence) ? d.evidence : [];
  const multipleSignals = evidence.length >= 2;

  const strongIndicator = (vtMalicious > 0) || (scamIntent === true) || multipleSignals;

  const eligible =
    Number.isFinite(riskScore) && riskScore >= 85 &&
    confidence === "High" &&
    strongIndicator;

  // Only eligible incidents continue down this branch.
  if (eligible) {
    out.push({ json: d });
  }
}

return out;

const out = [];

for (const item of $input.all()) {
  const d = (item && item.json) ? item.json : {};

  // Detect image scans: they carry extracted OCR text / input_type.
  const isImage = (d.input_type === "image") || (typeof d.extracted_text === "string");

  // Original text (text scans): prefer the real Telegram message text.
  let originalText;
  try {
    originalText = $('Telegram Trigger').item.json.message.text;
  } catch (e) {
    originalText = undefined;
  }
  if ((originalText === undefined || originalText === null) && typeof d.input === "string") {
    originalText = d.input;
  }

  const entities = (d.extracted_entities && typeof d.extracted_entities === "object") ? d.extracted_entities : {};

  const evidencePack = {
    scan_id: d.scan_id != null ? d.scan_id : (d.id != null ? d.id : null),
    timestamp: d.timestamp != null ? d.timestamp : null,
    platform: d.platform != null ? d.platform : "telegram",
    risk_score: d.risk_score != null ? d.risk_score : null,
    severity: d.severity != null ? d.severity : null,
    confidence: d.confidence != null ? d.confidence : null,
    threat_type: d.threat_type != null ? d.threat_type : null,
    extracted_entities: {
      urls: Array.isArray(entities.urls) ? entities.urls : [],
      upi_ids: Array.isArray(entities.upi_ids) ? entities.upi_ids : [],
      phone_numbers: Array.isArray(entities.phone_numbers) ? entities.phone_numbers : [],
      emails: Array.isArray(entities.emails) ? entities.emails : []
    },
    evidence: Array.isArray(d.evidence) ? d.evidence : [],
    ai_analysis: d.ai_analysis != null ? d.ai_analysis : null,
    virustotal: d.virustotal != null ? d.virustotal : null,
    recommendation: d.recommendation != null ? d.recommendation : null
  };

  // Original text only when actually available.
  if (originalText !== undefined && originalText !== null && originalText !== "") {
    evidencePack.original_text = originalText;
  }

  // Image scans: preserve extracted_text and mark input_type.
  if (isImage) {
    evidencePack.input_type = "image";
    if (typeof d.extracted_text === "string") {
      evidencePack.extracted_text = d.extracted_text;
    }
  } else {
    evidencePack.input_type = "text";
  }

  out.push({ json: { incident_evidence: evidencePack } });
}

return out;
